document.querySelectorAll('.status-btn').forEach(b=>b.addEventListener('click',()=>{document.getElementById('statusForm').action=b.dataset.action;document.getElementById('statusName').textContent=b.dataset.name;document.getElementById('statusValue').value=b.dataset.status;document.getElementById('referenceValue').value=b.dataset.reference||'';document.getElementById('noteValue').value=b.dataset.note||'';}));
document.querySelectorAll('.realize-btn').forEach(b=>b.addEventListener('click',()=>{const amount=document.getElementById('realizeAmount');document.getElementById('realizeForm').action=b.dataset.action;document.getElementById('realizeName').textContent=b.dataset.name;document.getElementById('realizeDate').value=b.dataset.date;amount.value=b.dataset.amount||b.dataset.max;amount.max=b.dataset.max;document.getElementById('realizeLimit').textContent='Maksimal sesuai prognosis: Rp '+Number(b.dataset.max||0).toLocaleString('id-ID');}));
const level=document.getElementById('budgetLevel'),parent=document.getElementById('budgetParent'),budgetAmount=document.getElementById('budgetAmount'),amountHelp=document.getElementById('budgetAmountHelp'),amountLabel=document.getElementById('budgetAmountLabel'),codingInfo=document.getElementById('codingBudgetInfo');const rupiahValue=value=>'Rp '+Number(value||0).toLocaleString('id-ID');function updateCodingBalance(){const isCoding=level.value==='subactivity';if(!isCoding){budgetAmount.removeAttribute('max');return;}const option=parent.options[parent.selectedIndex],budget=Number(option?.dataset.budget||0),used=Number(option?.dataset.used||0),current=Number(budgetAmount.value||0),remaining=budget-used-current;document.getElementById('codingParentBudget').textContent=rupiahValue(budget);document.getElementById('codingAlreadyUsed').textContent=rupiahValue(used);const remainingEl=document.getElementById('codingRemaining');remainingEl.textContent=rupiahValue(remaining);remainingEl.classList.toggle('text-danger',remaining<0);budgetAmount.max=Math.max(0,budget-used);}function filterParents(){const isCoding=level.value==='subactivity';parent.disabled=!isCoding;parent.required=isCoding;codingInfo.classList.toggle('d-none',!isCoding);if(!isCoding){parent.value='';budgetAmount.removeAttribute('max');}amountLabel.textContent=isCoding?'Rencana Nilai Kodering':'Jumlah Anggaran Sub Kegiatan';amountHelp.textContent=isCoding?'Nilai tidak boleh melebihi sisa Anggaran Sub Kegiatan.':'Masukkan pagu Sub Kegiatan/Rincian Belanja.';updateCodingBalance();}level.addEventListener('change',filterParents);parent.addEventListener('change',updateCodingBalance);budgetAmount.addEventListener('input',updateCodingBalance);filterParents();
const guInputs=[...document.querySelectorAll('.gu-allocation')],guRows=[...document.querySelectorAll('.gu-coding-row')],guInfo=document.getElementById('guAllocationInfo'),guParent=document.getElementById('guParent'),guAmount=document.getElementById('guAmount');function updateGuTotal(){const visibleInputs=guInputs.filter(input=>!input.closest('.gu-coding-row')?.classList.contains('d-none')),total=visibleInputs.reduce((sum,input)=>sum+Number(input.value||0),0),target=Number(guAmount?.value||0);if(guInfo){guInfo.textContent='Total pembagian: '+rupiahValue(total)+' dari '+rupiahValue(target);guInfo.className=Math.abs(total-target)<.01?'text-success fw-semibold':'text-danger fw-semibold';}}function filterGuCoding(){const selected=guParent.value,option=guParent.options[guParent.selectedIndex],budget=Number(option?.dataset.budget||0),used=Number(option?.dataset.gu||0),available=Math.max(0,budget-used);document.getElementById('guBudgetInfo').classList.toggle('d-none',!selected);document.getElementById('guSelectHint').classList.toggle('d-none',!!selected);document.getElementById('guParentBudget').textContent=rupiahValue(budget);document.getElementById('guParentUsed').textContent=rupiahValue(used);document.getElementById('guParentAvailable').textContent=rupiahValue(available);guAmount.max=available;document.getElementById('guAmountHelp').textContent=selected?'Maksimal GU yang dapat diinput: '+rupiahValue(available):'Pilih Sub Kegiatan untuk melihat anggaran tersedia.';guRows.forEach(row=>{const visible=selected&&row.dataset.parent===selected;row.classList.toggle('d-none',!visible);if(!visible)row.querySelector('.gu-allocation').value=0;});updateGuTotal();}guParent?.addEventListener('change',filterGuCoding);guAmount?.addEventListener('input',updateGuTotal);guInputs.forEach(input=>input.addEventListener('input',updateGuTotal));filterGuCoding();const expenseParent=document.getElementById('expenseParent'),expenseCoding=document.getElementById('expenseCoding'),expenseAmount=document.getElementById('expenseAmount');function updateExpenseCodingBudget(){const option=expenseCoding.options[expenseCoding.selectedIndex],selected=expenseCoding.value,budget=Number(option?.dataset.budget||0),used=Number(option?.dataset.used||0),current=Number(expenseAmount?.value||0),remaining=budget-used-current;document.getElementById('expenseBudgetInfo').classList.toggle('d-none',!selected);document.getElementById('expenseCodingBudget').textContent=rupiahValue(budget);document.getElementById('expenseCodingUsed').textContent=rupiahValue(used);const remainingEl=document.getElementById('expenseCodingRemaining');remainingEl.textContent=rupiahValue(remaining);remainingEl.classList.toggle('text-danger',remaining<0);if(selected)expenseAmount.max=Math.max(0,budget-used);else expenseAmount.removeAttribute('max');}function filterExpenseCoding(){const selected=expenseParent.value;expenseCoding.disabled=false;expenseCoding.value='';expenseAmount.value='';[...expenseCoding.options].forEach((codingOption,index)=>{if(index===0){codingOption.textContent=selected?'Pilih Kodering':'Pilih Sub Kegiatan terlebih dahulu';codingOption.hidden=false;return;}codingOption.hidden=codingOption.dataset.parent!==selected;});document.getElementById('expenseCodingHelp').textContent=selected?'Pilih salah satu Kodering milik Sub Kegiatan ini.':'Kodering akan tampil sesuai Sub Kegiatan yang dipilih.';updateExpenseCodingBudget();}expenseParent?.addEventListener('change',filterExpenseCoding);expenseCoding?.addEventListener('change',updateExpenseCodingBudget);expenseAmount?.addEventListener('input',updateExpenseCodingBudget);filterExpenseCoding();const directParent=document.getElementById('directParent'),directCoding=document.getElementById('directCoding'),directAmount=document.getElementById('directAmount');function updateDirectBalance(){const option=directCoding.options[directCoding.selectedIndex],selected=directCoding.value,budget=Number(option?.dataset.budget||0),gu=Number(option?.dataset.gu||0),realized=Number(option?.dataset.realized||0),budgetAvailable=Math.max(0,budget-realized),guAvailable=Math.max(0,gu-realized),maximum=Math.min(budgetAvailable,guAvailable);document.getElementById('directBalanceInfo').classList.toggle('d-none',!selected);document.getElementById('directBudget').textContent=rupiahValue(budget);document.getElementById('directGu').textContent=rupiahValue(gu);document.getElementById('directBudgetAvailable').textContent=rupiahValue(budgetAvailable);document.getElementById('directGuAvailable').textContent=rupiahValue(guAvailable);if(selected){directAmount.max=maximum;document.getElementById('directAmountHelp').textContent='Maksimal realisasi yang dapat dicatat: '+rupiahValue(maximum);}else{directAmount.removeAttribute('max');document.getElementById('directAmountHelp').textContent='Pilih Kodering untuk melihat saldo tersedia.';}}function filterDirectCoding(){const selected=directParent.value;directCoding.value='';[...directCoding.options].forEach((option,index)=>{if(index===0){option.textContent=selected?'Pilih Kodering':'Pilih Sub Kegiatan terlebih dahulu';option.hidden=false;return;}option.hidden=option.dataset.parent!==selected;});directAmount.value='';updateDirectBalance();}directParent?.addEventListener('change',filterDirectCoding);directCoding?.addEventListener('change',updateDirectBalance);filterDirectCoding();document.getElementById('budgetForm')?.addEventListener('submit',function(){const button=this.querySelector('button[type=submit],button:not([type])');if(button){button.disabled=true;button.innerHTML='<i class="bx bx-loader bx-spin me-1"></i>Menyimpan...';}});
</script>
